/**
 * `just up`. Sequences the modules; holds no logic of its own beyond argument parsing, so the
 * testable parts stay in their own files.
 */

import { createInterface } from 'node:readline/promises';
import { spawnResolved } from './command.mjs';
import { existsSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { resolveIdentifier } from './instance.mjs';
import { resolveDevServerPorts } from './ports.mjs';
import { renderAll } from './render.mjs';
import { formatReport, run, runChecks } from './preflight.mjs';
import { attachInstance, detachInstance, ensureProxy } from './proxy.mjs';
import { finishDevServers, selectDevServers, startDevServers } from './devservers.mjs';
